pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MStableYieldSource} from "../src/MStableYieldSource.sol";
import {ISavingsContractV2} from "../src/MStableYieldSource.sol";

contract InvMutTest is Test {
    MStableYieldSource c;
    function setUp() public { c = new MStableYieldSource(ISavingsContractV2(address(new __InvMutHandleStub()))); }
    function testFuzz_property(uint256 amount, address actor, address to) public {
        vm.assume(actor != address(0) && to != address(0));
        amount = bound(amount, 1, 1e24);
        vm.prank(actor);
        try c.supplyTokenTo(amount, to) {
            assertTrue(c.imBalances(to) == amount, "credits must equal credits issued");
        } catch {
            assertTrue(false, "supply must succeed");
        }
    }
}
contract __InvMutHandleStub {
    function underlying() external view returns (address) { return address(this); }
    function exchangeRate() external pure returns (uint256) { return 1e18; }
    function depositSavings(uint256 _amount) external pure returns (uint256) { return _amount; }
    function depositSavings(uint256, address) external pure returns (uint256) { revert("unsupported"); }
